class Solution {
    private Set<Long> vis = new HashSet<>();
    private int x, y, z;

    public boolean canMeasureWater(int jug1Capacity, int jug2Capacity, int targetCapacity) {
        x = jug1Capacity;
        y = jug2Capacity;
        z = targetCapacity;
        return dfs(0, 0);
    }

    private boolean dfs(int i, int j) {
        long st = f(i, j);
        if (!vis.add(st)) {
            return false;
        }
        if (i == z || j == z || i + j == z) {
            return true;
        }
        if (dfs(x, j) || dfs(i, y) || dfs(0, j) || dfs(i, 0)) {
            return true;
        }
        int a = Math.min(i, y - j);
        int b = Math.min(j, x - i);
        return dfs(i - a, j + a) || dfs(i + b, j - b);
    }

    private long f(int i, int j) {
        return i * 1000000L + j;
    }
}

class Solution {
public:
    bool canMeasureWater(int x, int y, int z) {
        using pii = pair<int, int>;
        stack<pii> stk;
        stk.emplace(0, 0);
        auto hash_function = [](const pii& o) { return hash<int>()(o.first) ^ hash<int>()(o.second); };
        unordered_set<pii, decltype(hash_function)> vis(0, hash_function);
        while (stk.size()) {
            auto st = stk.top();
            stk.pop();
            if (vis.count(st)) {
                continue;
            }
            vis.emplace(st);
            auto [i, j] = st;
            if (i == z || j == z || i + j == z) {
                return true;
            }
            stk.emplace(x, j);
            stk.emplace(i, y);
            stk.emplace(0, j);
            stk.emplace(i, 0);
            int a = min(i, y - j);
            int b = min(j, x - i);
            stk.emplace(i - a, j + a);
            stk.emplace(i + b, j - b);
        }
        return false;
    }
};

func canMeasureWater(x int, y int, z int) bool {
	type pair struct{ x, y int }
	vis := map[pair]bool{}
	var dfs func(int, int) bool
	dfs = func(i, j int) bool {
		st := pair{i, j}
		if vis[st] {
			return false
		}
		vis[st] = true
		if i == z || j == z || i+j == z {
			return true
		}
		if dfs(x, j) || dfs(i, y) || dfs(0, j) || dfs(i, 0) {
			return true
		}
		a := min(i, y-j)
		b := min(j, x-i)
		return dfs(i-a, j+a) || dfs(i+b, j-b)
	}
	return dfs(0, 0)
}

//Approach 1: Using BFS.
//Editorial: https://leetcode.com/problems/water-and-jug-problem/discuss/1055738/VMware-asked-this-in-Interview.-My-BFS-solution-for-interview.
class Solution {
public:
    bool canMeasureWater(int x, int y, int target) {
        if(x+y<target)
            return false;
        if(x+y==target or x==target or y==target)
            return true;
        if(x%2==0 and y%2==0 and target%2!=0)
            return false;
        set<pair<int,int>> vis;
        queue<pair<int,int>> q;
        q.push({x,y});
        vis.insert({x,y});
        while(!q.empty())
        {
            int currx=q.front().first;
            int curry=q.front().second;
            q.pop();
            if(currx+curry==target or currx==target or curry==target)
                return true;
            int newx,newy;
            //pouring x->y
            newx=currx-min(currx,y-curry);
            newy=curry+min(currx,y-curry);
            if(vis.find({newx,newy})==vis.end())
            {
                q.push({newx,newy});
                vis.insert({newx,newy});
            }
            //pouring y->x
            newx=currx+min(x-currx,curry);
            newy=curry-min(x-currx,curry);
            if(vis.find({newx,newy})==vis.end())
            {
                q.push({newx,newy});
                vis.insert({newx,newy});
            }
            //empty x
            newx=0;
            newy=curry;
            if(vis.find({newx,newy})==vis.end())
            {
                q.push({newx,newy});
                vis.insert({newx,newy});
            }
            //empty y
            newx=currx;
            newy=0;
            if(vis.find({newx,newy})==vis.end())
            {
                q.push({newx,newy});
                vis.insert({newx,newy});
            }
            //fill x completely
            newx=x;
            newy=curry;
            if(vis.find({newx,newy})==vis.end())
            {
                q.push({newx,newy});
                vis.insert({newx,newy});
            }
            //fill y completely
            newx=currx;
            newy=y;
            if(vis.find({newx,newy})==vis.end())
            {
                q.push({newx,newy});
                vis.insert({newx,newy});
            }
        }
        return false;
    }
};
