class Solution {
public:
    bool canMeasureWater(int x, int y, int target) {
        if(x+y<target)
            return false;
        if(x+y==target or x==target or y==target)
            return true;
        if(x%2==0 and y%2==0 and target%2!=0)
            return false;
        return target%__gcd(x,y)==0;
    }
};
